import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = list(reader)

    def clean_header_cell(value):
        return value.lstrip("\ufeff")

    expected_header = ("concept", "preflabel", "altlabels")
    header_index = None

    for index, record in enumerate(records):
        normalized = tuple(clean_header_cell(value).strip().lower() for value in record)
        if normalized == expected_header:
            header_index = index
            break

    if header_index is None:
        header_index = next(
            (index for index, record in enumerate(records) if any(value.strip() for value in record)),
            0,
        )

    header = [clean_header_cell(value) for value in records[header_index]] if records else []
    width = 3
    if len(header) > width:
        header = header[:width - 1] + [",".join(header[width - 1:])]
    else:
        header.extend([""] * (width - len(header)))

    rows = []
    for record in records[header_index + 1:]:
        if len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        else:
            record = record + [""] * (width - len(record))
        rows.append(record)

    return {"columns": header, "rows": rows}
